"use strict";
let gameLibraryFilter='all',gameLibraryQuery='',gameLibraryFavorites=[],gameLibraryRecent=[];
const libraryGames=()=>[...pocketClassicGames,...pocketJavaGames];
try{const p=JSON.parse(localStorage.getItem('olddays-game-library')||'{}'),ids=libraryGames().map(g=>g.id);gameLibraryFavorites=Array.isArray(p.favorites)?p.favorites.filter(id=>ids.includes(id)).slice(0,30):[];gameLibraryRecent=Array.isArray(p.recent)?p.recent.filter(id=>ids.includes(id)).slice(0,5):[];}catch{}
function gameLibraryType(id){return ['ancient-empires-2','grid-tactics','keypad-chess','tower-guard'].includes(id)?'tactics':['pokemon-crystal','pocket-saga','monster-duel','dungeon-quest'].includes(id)?'rpg':'casual';}
function saveGameLibrary(){try{localStorage.setItem('olddays-game-library',JSON.stringify({favorites:gameLibraryFavorites,recent:gameLibraryRecent}));}catch{}}
function gameLibraryRows(){return libraryGames().filter(g=>(gameLibraryFilter==='all'||gameLibraryFilter==='favorites'&&gameLibraryFavorites.includes(g.id)||gameLibraryFilter===gameLibraryType(g.id))&&g.title.toLowerCase().includes(gameLibraryQuery.toLowerCase().trim()));}
phoneGameShelfMarkup=function(){const rows=gameLibraryRows();return '<section class="phone-game-shelf game-library"><header><small>ONE MORE GAME / 游戏收藏夹</small><h2>今晚，再玩一局。</h2><p>战棋、升级冒险和课间小游戏。经典存档与本站开源重制分别标明。</p></header><form data-game-library-search><input aria-label="搜索游戏" name="query" value="'+escapeHTML(gameLibraryQuery)+'" placeholder="搜战棋、勇者、精灵"><button>查找</button></form><nav class="game-library-filters">'+[['all','全部'],['tactics','战棋策略'],['rpg','升级冒险'],['casual','休闲'],['favorites','我的收藏']].map(([id,t])=>'<button data-game-library-filter="'+id+'" aria-pressed="'+(gameLibraryFilter===id)+'">'+t+'</button>').join('')+'</nav>'+(gameLibraryRecent.length?'<details><summary>最近玩过</summary>'+gameLibraryRecent.map(id=>{const g=libraryGames().find(g=>g.id===id);return '<button data-launch-java="'+id+'">'+escapeHTML(g.title)+'</button>';}).join('')+'</details>':'')+'<button class="phone-native-game" data-phone-snake>▦ 原生贪吃蛇</button><p>'+rows.length+' 个结果 / '+libraryGames().length+' 款口袋游戏</p>'+rows.map(g=>'<article class="game-library-row"><button data-launch-java="'+g.id+'"><b>'+escapeHTML(g.title)+'</b><small>'+(pocketClassicGames.some(x=>x.id===g.id)?(g.id==='pokemon-crystal'?'历史存档 · 英文版 · GBC兼容运行':'历史存档 · 英文版 · Java ME'):'开源重制 · Java ME')+'</small><span>开始游戏 →</span></button><button data-game-library-star="'+g.id+'" aria-label="'+(gameLibraryFavorites.includes(g.id)?'取消收藏 ':'收藏 ')+escapeHTML(g.title)+'">'+(gameLibraryFavorites.includes(g.id)?'★':'☆')+'</button></article>').join('')+(rows.length?'':'<p>暂时没有找到，换个名字或切换分类。</p>')+'<aside class="game-library-maintenance">古代帝国 II：手机菜单显示尚在维护，暂不提供启动入口；已有存档保留。</aside><details><summary>存档与按键小贴士</summary><p>方向键移动，5 确认；左、右软键用于菜单和返回。战棋的 # 可结束回合。经典游戏语言以实际版本为准。进度保存在当前浏览器。存档盒包含收藏和网页阅读记录，不包含 Java 模拟器内部进度；请勿清除网站数据。</p><p>水晶：5=A，0=B，#=Start，1即时存档、3读档。</p></details></section>';};
document.addEventListener('click',e=>{const b=e.target.closest('[data-game-library-filter],[data-game-library-star],[data-launch-java]');if(!b)return;if(b.dataset.launchJava){if(!libraryGames().some(g=>g.id===b.dataset.launchJava))return;gameLibraryRecent=[b.dataset.launchJava,...gameLibraryRecent.filter(id=>id!==b.dataset.launchJava)].slice(0,5);saveGameLibrary();return;}e.preventDefault();if(b.dataset.gameLibraryFilter&&['all','tactics','rpg','casual','favorites'].includes(b.dataset.gameLibraryFilter))gameLibraryFilter=b.dataset.gameLibraryFilter;if(b.dataset.gameLibraryStar&&libraryGames().some(g=>g.id===b.dataset.gameLibraryStar)){const id=b.dataset.gameLibraryStar;gameLibraryFavorites=gameLibraryFavorites.includes(id)?gameLibraryFavorites.filter(x=>x!==id):[...gameLibraryFavorites,id];saveGameLibrary();}refreshPhone();},true);
document.addEventListener('submit',e=>{if(!e.target.matches('[data-game-library-search]'))return;e.preventDefault();gameLibraryQuery=String(new FormData(e.target).get('query')||'').slice(0,60);refreshPhone();});

let bookLibraryQuery='';
const libraryBookBase=phoneBookMarkup;
phoneBookMarkup=function(){if(phoneState.book)return libraryBookBase();const all=readingShelf(),q=bookLibraryQuery.trim().toLowerCase(),books=all.filter(b=>(b.title+' '+b.author+' '+b.label).toLowerCase().includes(q));const recent=all.filter(b=>Object.hasOwn(readingState.progress,b.id));return '<section class="phone-book-library"><header><small>夜读书架 / 本机续读</small><h2>再看一回，就睡。</h2><p>'+all.length+' 本原创与公版作品，正文可翻章阅读。</p></header><form data-book-library-search><input name="query" aria-label="搜索书名或作者" placeholder="书名 / 作者" value="'+escapeHTML(bookLibraryQuery)+'"><button>找书</button></form>'+(recent.length?'<details open><summary>继续上次的书</summary>'+recent.slice(0,4).map(b=>'<button data-phone-read="'+b.id+'">'+escapeHTML(b.title)+' · 第 '+(readingState.progress[b.id]+1)+' 回</button>').join('')+'</details>':'')+'<p>'+books.length+' 个结果</p>'+books.map(b=>'<button class="phone-book-entry" data-phone-read="'+b.id+'"><b>'+escapeHTML(b.title)+'</b><small>'+escapeHTML(b.author)+' · '+b.chapterCount+' 回<br>'+escapeHTML(b.label)+'</small></button>').join('')+(books.length?'':'<p>没有找到，换一个书名或作者试试。</p>')+'<p class="phone-small-note">公版经典与原创分别标注。阅读位置保存在本机，恢复备份可继续阅读。</p></section>';};
document.addEventListener('submit',e=>{if(!e.target.matches('[data-book-library-search]'))return;e.preventDefault();bookLibraryQuery=String(new FormData(e.target).get('query')||'').slice(0,60);refreshPhone();});
